def generator(rng):
    C = rng.randint(2, 5)
    N = rng.randint(4, 12)
    B = 2 * rng.randint(2, 6)

    # To prevent A from becoming excessively large, we can add a constraint.
    # For example, C=5, N=12 gives A > 244 million. Let's cap N based on C.
    if C == 3:
        N = rng.randint(4, 10)
    elif C == 4:
        N = rng.randint(4, 8)
    elif C == 5:
        N = rng.randint(4, 6)

    A = C**N
    return {
        'C': C,
        'N': N,
        'B': B,
        'A': A
    }
